define([],function(){const MARGIN=8;const place=function(tip,el){const text=el.getAttribute("data-tip")||"";if(!text){return}tip.textContent=text;tip.classList.add("is-on");const r=el.getBoundingClientRect();const tw=tip.offsetWidth;const th=tip.offsetHeight;let left=r.left+(r.width/2)-(tw/2);let top=r.top-th-6;if(top<MARGIN){top=r.bottom+6}if(left<MARGIN){left=MARGIN}if(left+tw>window.innerWidth-MARGIN){left=Math.max(MARGIN,window.innerWidth-MARGIN-tw)}if(top+th>window.innerHeight-MARGIN){top=Math.max(MARGIN,r.top-th-6)}tip.style.left=Math.round(left)+"px";tip.style.top=Math.round(top)+"px"};const init=function(){const root=document.querySelector("[data-region=nexprofile]");if(!root){return}const heat=root.querySelector(".nxp-heat");if(!heat){return}heat.classList.add("nxp-heat--js-tip");heat.querySelectorAll(".nxp-heat__cell[title]").forEach(function(el){el.removeAttribute("title")});let tip=document.querySelector(".nxp-heat-tip");if(!tip){tip=document.createElement("div");tip.className="nxp-heat-tip";tip.setAttribute("role","tooltip");document.body.appendChild(tip)}let active=null;const showFor=function(el){if(!el||!el.getAttribute("data-tip")){return}active=el;place(tip,el)};const hide=function(){active=null;tip.classList.remove("is-on")};heat.addEventListener("pointerover",function(e){const cell=e.target.closest(".nxp-heat__cell[data-tip]");if(cell){showFor(cell)}});heat.addEventListener("pointerout",function(e){const cell=e.target.closest(".nxp-heat__cell[data-tip]");if(!cell){return}const next=e.relatedTarget&&e.relatedTarget.closest?e.relatedTarget.closest(".nxp-heat__cell[data-tip]"):null;if(next!==cell){hide()}});heat.addEventListener("focusin",function(e){const cell=e.target.closest(".nxp-heat__cell[data-tip]");if(cell){showFor(cell)}});heat.addEventListener("focusout",hide);window.addEventListener("scroll",function(){if(active){place(tip,active)}},true);window.addEventListener("resize",hide)};return{init:init}});
